(function() {
    // 获取蒜子服务的域名（从当前脚本的 src 属性提取）
    function getSuanziHost() {
        var scripts = document.getElementsByTagName('script');
        for (var i = 0; i < scripts.length; i++) {
            var src = scripts[i].src;
            if (src.indexOf('suanzi.min.js') !== -1 || src.indexOf('busuanzi.min.js') !== -1) {
                // 提取域名部分，如 //suanzi.cakepanit.com 或 http://example.com:7788
                var match = src.match(/^(https?:)?\/\/([^\/\s]+)/);
                if (match) {
                    return match[2]; // 返回域名（不含协议）
                }
            }
        }
        return 'suanzi.cakepanit.com'; // 默认
    }

    // 生成 UUID
    function generateUUID() {
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
            var r = Math.random() * 16 | 0,
                v = c == 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        });
    }

    // Cookie 操作
    function getCookie(name) {
        var nameEQ = name + "=";
        var ca = document.cookie.split(';');
        for(var i = 0; i < ca.length; i++) {
            var c = ca[i];
            while (c.charAt(0) == ' ') c = c.substring(1, c.length);
            if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length, c.length);
        }
        return null;
    }

    function setCookie(name, value, days) {
        var expires = "";
        if (days) {
            var date = new Date();
            date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
            expires = "; expires=" + date.toUTCString();
        }
        document.cookie = name + "=" + (value || "") + expires + "; path=/";
    }

    // 获取域名
    function getDomain() {
        return window.location.hostname;
    }

    // 获取当前页面路径
    function getPath() {
        return window.location.pathname;
    }

    // 获取或创建用户 UUID
    function getUserUUID() {
        var uuid = getCookie('suanzi_uuid');
        if (!uuid) {
            uuid = generateUUID();
            setCookie('suanzi_uuid', uuid, 365); // 有效期 1 年
        }
        return uuid;
    }

    // 批量计数并回填
    function batchCountAndFill() {
        var suanziHost = getSuanziHost();
        var domain = getDomain();
        var uuid = getUserUUID();
        var path = getPath();

        // 收集页面上所有需要显示的计数类型
        var types = [];
        if (document.getElementById('suanzi_value_site_pv')) types.push('site_pv');
        if (document.getElementById('suanzi_value_site_uv')) types.push('site_uv');
        if (document.getElementById('suanzi_value_page_pv')) types.push('page_pv');

        if (types.length === 0) return; // 页面上没有需要显示的计数器

        // 一次 POST 提交所有类型
        var data = {
            domain: domain,
            uuid: uuid,
            path: path,
            types: types
        };

        // 使用完整 URL 请求蒜子服务
        var apiUrl = '//' + suanziHost + '/api/count';
        fetch(apiUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(data)
        })
        .then(function(response) {
            return response.json();
        })
        .then(function(result) {
            // 回填计数值
            if (result.counts) {
                for (var type in result.counts) {
                    var elementId = 'suanzi_value_' + type;
                    var element = document.getElementById(elementId);
                    if (element) {
                        element.textContent = result.counts[type].toLocaleString();
                    }
                }
            }
        })
        .catch(function(error) {
            console.log('批量计数请求失败:', error);
        });
    }

    // 页面加载完成后执行
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', batchCountAndFill);
    } else {
        batchCountAndFill();
    }
})();
